SELECT school_name, COUNT(school_name) AS count FROM `study_up` WHERE deleted =0
AND plan_time between #{startTime} AND #{endTime}
GROUP BY school_name ORDER BY COUNT(school_name) DESC LIMIT 0, 10

SELECT major AS name, COUNT(school_type) AS value FROM study_up WHERE deleted =0
AND plan_time between #{startTime} AND #{endTime}
GROUP BY major

SELECT school_type AS name, COUNT(school_type) AS value FROM study_up WHERE deleted =0
AND plan_time between #{startTime} AND #{endTime}
GROUP BY school_type
